import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  MdPerson,
  MdLock,
  MdVisibility,
  MdVisibilityOff,
} from "react-icons/md";
import logo from "../image/yonko1.jpeg";
import {
  saveOfflineCredentials,
  verifyOfflineCredentials,
} from "../utils/offlineAuth";

function OfficerAccess() {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const navigate = useNavigate();

  useEffect(() => {
    const card = document.querySelector(".light-card");

    if (card) {
      card.style.opacity = "1";
      card.style.transform = "translateY(0)";
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => {
      setIsOffline(false);
      setErrorMessage("");
    };

    const handleOffline = () => {
      setIsOffline(true);
      setErrorMessage(
        "You are offline. Use your registered offline credentials to login."
      );
    };

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  const handleLogin = async (e) => {
  e.preventDefault();
  setErrorMessage("");

  if (!identifier.trim()) {
    setErrorMessage("Please enter your username.");
    return;
  }

  if (!password) {
    setErrorMessage("Please enter your password.");
    return;
  }

  setIsLoading(true);

  const normalizedIdentifier = identifier.trim();

  const loginOffline = async () => {
    const offlineRecord = await verifyOfflineCredentials({
      identifier: normalizedIdentifier,
      password,
    });

    if (!offlineRecord) {
      throw new Error(
        "Offline login failed. Incorrect username or password, or this account has not been enabled for offline login on this device."
      );
    }

    const offlineUser = offlineRecord.user;

    const userRole = offlineUser?.role
      ?.toString()
      ?.trim()
      ?.toLowerCase();

    if (userRole !== "loan_officer") {
      throw new Error(
        "Access denied. This account does not have Loan Officer access."
      );
    }

    localStorage.setItem(
      "user",
      JSON.stringify(offlineUser)
    );

    localStorage.setItem(
      "role",
      "loan_officer"
    );

    localStorage.setItem(
      "offlineMode",
      "true"
    );

    sessionStorage.setItem(
      "loginRoute",
      "/officer-access"
    );

    navigate("/officer-dashboard", {
      replace: true,
    });
  };

  try {
    /*
     * ============================================================
     * TRUE OFFLINE
     * ============================================================
     */
    if (!navigator.onLine) {
      await loginOffline();
      return;
    }

    /*
     * ============================================================
     * ONLINE LOGIN
     * ============================================================
     */
    const API_BASE_URL =
      process.env.REACT_APP_API_URL || "";

    const controller = new AbortController();

    // Do not allow the login request to hang indefinitely.
    const timeoutId = setTimeout(() => {
      controller.abort();
    }, 10000);

    let response;

    try {
      response = await fetch(
        `${API_BASE_URL}/login2`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            identifier: normalizedIdentifier,
            password,
          }),
          signal: controller.signal,
        }
      );
    } finally {
      clearTimeout(timeoutId);
    }

    let data = {};

    try {
      data = await response.json();
    } catch {
      data = {};
    }

    if (!response.ok) {
      throw new Error(
        data.message || "Login failed."
      );
    }

    if (!data.token || !data.user) {
      throw new Error(
        "Invalid login response from server."
      );
    }

    /*
     * ============================================================
     * CHECK ROLE
     * ============================================================
     */
    const userRole = data.user?.role
      ?.toString()
      ?.trim()
      ?.toLowerCase();

    if (userRole !== "loan_officer") {
      throw new Error(
        `Access denied. This account has the role "${data.user?.role}". Loan Officer access is required.`
      );
    }

    /*
     * ============================================================
     * SAVE ONLINE SESSION
     * ============================================================
     */
    localStorage.setItem(
      "token",
      data.token
    );

    localStorage.setItem(
      "user",
      JSON.stringify(data.user)
    );

    localStorage.setItem(
      "role",
      "loan_officer"
    );

    localStorage.removeItem(
      "offlineMode"
    );

    sessionStorage.setItem(
      "loginRoute",
      "/officer-access"
    );

    /*
     * ============================================================
     * SAVE OFFLINE CREDENTIALS
     * ============================================================
     */
    try {
      await saveOfflineCredentials({
        identifier: normalizedIdentifier,
        password,
        user: data.user,
      });

      console.log(
        "Offline authentication enabled for this device."
      );
    } catch (offlineError) {
      console.error(
        "Could not save offline authentication:",
        offlineError
      );
    }

    navigate("/officer-dashboard", {
      replace: true,
    });
  } catch (error) {
    console.error(
      "Officer login error:",
      error
    );

    /*
     * ============================================================
     * API FAILED / TIMEOUT
     * ============================================================
     *
     * Even if navigator.onLine is true, the API itself
     * may be unreachable. Try IndexedDB authentication.
     */
    const isConnectionError =
      error?.name === "AbortError" ||
      error?.name === "TypeError" ||
      !navigator.onLine;

    if (isConnectionError) {
      try {
        await loginOffline();
        return;
      } catch (offlineError) {
        console.error(
          "Offline authentication error:",
          offlineError
        );

        setErrorMessage(
          offlineError?.message ||
            "Unable to connect to the server and offline login is not available."
        );

        return;
      }
    }

    setErrorMessage(
      error?.message ||
        "An error occurred while logging in."
    );
  } finally {
    setIsLoading(false);
  }
};

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background: "#ffffff",
        padding: "20px",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div className="shape shape-1" />
      <div className="shape shape-2" />
      <div className="shape shape-3" />

      <div
        className="light-card"
        style={{
          width: "100%",
          maxWidth: "460px",
          background: "#ffffff",
          borderRadius: "32px",
          padding: "48px 40px 40px",
          boxShadow:
            "0 20px 60px rgba(0,0,0,0.06), 0 8px 24px rgba(0,0,0,0.03)",
          border: "1px solid rgba(0,0,0,0.04)",
          opacity: 0,
          transform: "translateY(30px)",
          transition:
            "opacity 0.8s ease, transform 0.8s ease",
          position: "relative",
          zIndex: 10,
          boxSizing: "border-box",
        }}
      >
        {/* HEADER */}
        <div
          style={{
            textAlign: "center",
            marginBottom: "36px",
          }}
        >
          <div
            style={{
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
              width: "80px",
              height: "80px",
              borderRadius: "24px",
              background: "#f8faff",
              boxShadow:
                "0 8px 24px rgba(99,102,241,0.10)",
              overflow: "hidden",
              animation:
                "floatLogo 4s ease-in-out infinite",
            }}
          >
            <img
              src={logo}
              alt="Yonkopa"
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
          </div>

          <h2
            style={{
              margin: "16px 0 4px",
              fontSize: "26px",
              fontWeight: "600",
              color: "#1e293b",
              letterSpacing: "-0.5px",
            }}
          >
            Yonkopa Micro Credit
          </h2>

          <p
            style={{
              margin: 0,
              color: "#94a3b8",
              fontSize: "14px",
              fontWeight: "400",
              letterSpacing: "0.5px",
              textTransform: "uppercase",
            }}
          >
            Officer Portal
          </p>

          {isOffline && (
            <div
              style={{
                marginTop: "16px",
                padding: "9px 14px",
                borderRadius: "10px",
                background: "#fff7ed",
                color: "#c2410c",
                border: "1px solid #fed7aa",
                fontSize: "13px",
                fontWeight: "500",
              }}
            >
              Offline Mode – Offline login available
            </div>
          )}
        </div>

        {/* LOGIN FORM */}
        <form onSubmit={handleLogin}>
          {/* Username */}
          <div style={{ marginBottom: "24px" }}>
            <label
              htmlFor="identifier"
              style={{
                display: "block",
                marginBottom: "8px",
                fontSize: "13px",
                fontWeight: "600",
                color: "#334155",
                letterSpacing: "0.3px",
                textTransform: "uppercase",
              }}
            >
              Username
            </label>

            <div style={{ position: "relative" }}>
              <span
                style={{
                  position: "absolute",
                  left: "16px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  color: "#94a3b8",
                  fontSize: "20px",
                  display: "flex",
                  alignItems: "center",
                  zIndex: 2,
                }}
              >
                <MdPerson />
              </span>

              <input
                id="identifier"
                type="text"
                value={identifier}
                onChange={(e) =>
                  setIdentifier(e.target.value)
                }
                placeholder="Enter your username"
                required
                autoComplete="username"
                disabled={isLoading}
                style={{
                  width: "100%",
                  padding: "14px 16px 14px 48px",
                  background: "#f8fafc",
                  border: "1.5px solid #e2e8f0",
                  borderRadius: "14px",
                  fontSize: "15px",
                  color: "#1e293b",
                  outline: "none",
                  transition: "all 0.3s ease",
                  boxSizing: "border-box",
                  opacity: 1,
                }}
                onFocus={(e) => {
                  e.target.style.borderColor =
                    "#818cf8";
                  e.target.style.boxShadow =
                    "0 0 0 4px rgba(129,140,248,0.12)";
                  e.target.style.background =
                    "#ffffff";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor =
                    "#e2e8f0";
                  e.target.style.boxShadow =
                    "none";
                  e.target.style.background =
                    "#f8fafc";
                }}
              />
            </div>
          </div>

          {/* Password */}
          <div style={{ marginBottom: "24px" }}>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "8px",
              }}
            >
              <label
                htmlFor="password"
                style={{
                  fontSize: "13px",
                  fontWeight: "600",
                  color: "#334155",
                  letterSpacing: "0.3px",
                  textTransform: "uppercase",
                }}
              >
                Password
              </label>

              <button
                type="button"
                onClick={() =>
                  setErrorMessage(
                    "Please contact your administrator to reset your password."
                  )
                }
                style={{
                  border: "none",
                  background: "transparent",
                  fontSize: "13px",
                  color: "#818cf8",
                  cursor: "pointer",
                  fontWeight: "500",
                  padding: 0,
                }}
              >
                Forgot?
              </button>
            </div>

            <div style={{ position: "relative" }}>
              <span
                style={{
                  position: "absolute",
                  left: "16px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  color: "#94a3b8",
                  fontSize: "20px",
                  display: "flex",
                  alignItems: "center",
                  zIndex: 2,
                }}
              >
                <MdLock />
              </span>

              <input
                id="password"
                type={
                  showPassword
                    ? "text"
                    : "password"
                }
                value={password}
                onChange={(e) =>
                  setPassword(e.target.value)
                }
                required
                autoComplete="current-password"
                disabled={isLoading}
                style={{
                  width: "100%",
                  padding:
                    "14px 52px 14px 48px",
                  background: "#f8fafc",
                  border:
                    "1.5px solid #e2e8f0",
                  borderRadius: "14px",
                  fontSize: "15px",
                  color: "#1e293b",
                  outline: "none",
                  transition: "all 0.3s ease",
                  boxSizing: "border-box",
                  opacity: 1,
                }}
                onFocus={(e) => {
                  e.target.style.borderColor =
                    "#818cf8";
                  e.target.style.boxShadow =
                    "0 0 0 4px rgba(129,140,248,0.12)";
                  e.target.style.background =
                    "#ffffff";
                }}
                onBlur={(e) => {
                  e.target.style.borderColor =
                    "#e2e8f0";
                  e.target.style.boxShadow =
                    "none";
                  e.target.style.background =
                    "#f8fafc";
                }}
              />

              <button
                type="button"
                onClick={() =>
                  setShowPassword(
                    (prev) => !prev
                  )
                }
                disabled={isLoading}
                aria-label={
                  showPassword
                    ? "Hide password"
                    : "Show password"
                }
                style={{
                  position: "absolute",
                  right: "14px",
                  top: "50%",
                  transform:
                    "translateY(-50%)",
                  background: "transparent",
                  border: "none",
                  color: "#94a3b8",
                  cursor: "pointer",
                  fontSize: "20px",
                  padding: "4px",
                  display: "flex",
                  alignItems: "center",
                }}
              >
                {showPassword ? (
                  <MdVisibilityOff />
                ) : (
                  <MdVisibility />
                )}
              </button>
            </div>
          </div>

          {/* Error message */}
          {errorMessage && (
            <div
              role="alert"
              style={{
                backgroundColor: "#fee2e2",
                color: "#b91c1c",
                padding: "12px 16px",
                borderRadius: "10px",
                marginBottom: "20px",
                fontSize: "14px",
                border:
                  "1px solid #fecaca",
                lineHeight: "1.5",
              }}
            >
              {errorMessage}
            </div>
          )}

          {/* Login Button */}
          <button
            type="submit"
            disabled={isLoading}
            style={{
              width: "100%",
              padding: "16px",
              background: isLoading
                ? "#c7d2fe"
                : "linear-gradient(135deg, #0474cf 0%, #2b6dfc 100%)",
              color: "#fff",
              border: "none",
              borderRadius: "14px",
              fontSize: "16px",
              fontWeight: "600",
              cursor: isLoading
                ? "not-allowed"
                : "pointer",
              transition: "all 0.3s ease",
              boxShadow:
                "0 8px 30px rgba(99,102,241,0.25)",
              position: "relative",
              overflow: "hidden",
              letterSpacing: "0.5px",
              minHeight: "56px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: 1,
            }}
            onMouseEnter={(e) => {
              if (!isLoading) {
                e.currentTarget.style.transform =
                  "translateY(-3px) scale(1.02)";
                e.currentTarget.style.boxShadow =
                  "0 12px 40px rgba(99,102,241,0.35)";
              }
            }}
            onMouseLeave={(e) => {
              if (!isLoading) {
                e.currentTarget.style.transform =
                  "translateY(0) scale(1)";
                e.currentTarget.style.boxShadow =
                  "0 8px 30px rgba(99,102,241,0.25)";
              }
            }}
          >
            {isLoading ? (
              <span
                style={{
                  display: "inline-block",
                  width: "24px",
                  height: "24px",
                  border:
                    "3px solid rgba(255,255,255,0.3)",
                  borderTopColor: "#fff",
                  borderRadius: "50%",
                  animation:
                    "spin 0.8s linear infinite",
                }}
              />
            ) : isOffline ? (
              "Login Offline →"
            ) : (
              "Login →"
            )}
          </button>
        </form>

        {/* Footer */}
        <div
          style={{
            marginTop: "32px",
            paddingTop: "20px",
            borderTop:
              "1px solid #f1f5f9",
            textAlign: "center",
            fontSize: "12px",
            color: "#94a3b8",
            letterSpacing: "0.3px",
          }}
        >
          © {new Date().getFullYear()} Yonkopa Micro Credit
        </div>
      </div>

      <style>
        {`
          @keyframes floatLogo {
            0%, 100% {
              transform: translateY(0);
            }

            50% {
              transform: translateY(-6px);
            }
          }

          @keyframes spin {
            to {
              transform: rotate(360deg);
            }
          }

          .shape {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            opacity: 0.08;
            animation: floatShape 12s ease-in-out infinite;
          }

          .shape-1 {
            width: 300px;
            height: 300px;
            background: #818cf8;
            top: -120px;
            right: -80px;
            animation-delay: 0s;
          }

          .shape-2 {
            width: 400px;
            height: 400px;
            background: #a78bfa;
            bottom: -160px;
            left: -120px;
            animation-delay: -4s;
          }

          .shape-3 {
            width: 200px;
            height: 200px;
            background: #c4b5fd;
            top: 40%;
            left: 10%;
            animation-delay: -8s;
          }

          .light-card {
            animation: cardAppear 0.9s ease forwards;
          }

          @keyframes floatShape {
            0%, 100% {
              transform: translate(0, 0) scale(1);
            }

            33% {
              transform: translate(40px, -50px) scale(1.1);
            }

            66% {
              transform: translate(-30px, 30px) scale(0.9);
            }
          }

          @keyframes cardAppear {
            0% {
              opacity: 0;
              transform: translateY(40px) scale(0.96);
            }

            100% {
              opacity: 1;
              transform: translateY(0) scale(1);
            }
          }

          @media (max-width: 520px) {
            .light-card {
              padding: 40px 24px 30px !important;
              border-radius: 24px !important;
            }
          }
        `}
      </style>
    </div>
  );
}

export default OfficerAccess;